style.css:
/* Strawberry Milk | Roblox */

:root {
  /* puedes cambiar estos colores */
  --my-pink: #ffc5df;
  --my-light-pink: #ffe6f2;
  --my-white: #fffaff;
  --my-text: #563447;
  --my-accent: #e879ad;
}

/* fondo */
html,
body {
  background-color: var(--my-light-pink) !important;
  color: var(--my-text) !important;
}

/* paneles y tarjetas */
section,
article,
main {
  background-color: var(--my-white) !important;
  color: var(--my-text) !important;
  border-radius: 16px !important;
}

/* letras visibles */
p,
span,
label,
h1,
h2,
h3,
h4 {
  color: var(--my-text) !important;
}

/* enlaces */
a {
  color: #c94f91 !important;
}

/* botones */
button {
  background-color: var(--my-pink) !important;
  color: #563447 !important;
  border: 1px solid #f2a9ce !important;
  border-radius: 12px !important;
}

/* campos de texto */
input,
textarea,
select {
  background-color: #fffaff !important;
  color: #563447 !important;
  border: 1px solid #f2a9ce !important;
  border-radius: 10px !important;
}

/* imágenes y tarjetas */
img {
  border-radius: 12px !important;
}
